function generate(rand, size) {
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 12);
  const letters = size === 'large' ? 1 + Math.floor(rand() * 26) : 1 + Math.floor(rand() * 4);
  const offset = Math.floor(rand() * (27 - letters));
  let s = '';
  for (let i = 0; i < n; i++) s += String.fromCharCode(97 + offset + Math.floor(rand() * letters));
  return [s];
}
